H = {'1.1': [('Each one alone is not enough: flow ties the other two together.', "A crowd's ID card has three lines: how packed, how fast, how many pass."), ('Each phase moves people in a different pattern with its own peak.', 'In, around, out: a door, a roundabout and an exit sign.'), ('Only the excess over capacity accumulates.', 'A bath gaining 40 cups of water a minute for half an hour.'), ('Growth stops when inflow equals outflow, not when inflow is largest.', 'A bath still fills while you turn the tap down, until the flow falls below the drain.'), ('Blaming panic hides the fixable causes.', "A packed lift cannot 'panic' its way into being less full."), ('Queue growth = arrivals − capacity: change either side.', 'Widen the plughole, or turn down the tap.')], '1.2': [('It is a count divided by an area.', 'A ruler drawing a 1 m square and counting the heads inside.'), ('Invert density to get space per person.', 'Three people sharing one doormat.'), ('A is the most space; F the least.', 'Grade A: an empty park with one jogger.'), ('Movement needs extra space in front of each person.', 'A queue packs like parked cars; a corridor flows like moving cars needing gaps.'), ('Holding capacity = area × density.', '1,600 tiles, two people on each.'), ('Risk is local, not average.', 'Half a pizza can still have all the toppings on one slice.')], '1.3': [('Flow counts people crossing a line: more people and faster people both add flow.', 'A conveyor belt: items per metre × belt speed = items per second.'), ('Multiply by width last.', 'Three lanes, each passing 1.2 people a second.'), ('A product of a rising and a falling quantity has a maximum.', 'Adding cooks: at first faster cooking, then too many cooks and less food.'), ('That is where density × speed is largest.', "1.2 people per metre per second, like one person and a child's arm."), ("The curve's parameters depend on who walks.", "Using a sprinter's timetable for a walking group."), ('Near the peak, both branches are close.', 'A pencil balanced on its tip: a nudge sends it down one side.')], '1.4': [('Flow cannot exceed the weakest link.', "A funnel's neck decides how fast it empties."), ('Time = people ÷ capacity.', 'Two people a second for eight and a half minutes.'), ('Laboratory crowds, motivated but not pushing.', 'Between one and two people per metre each second.'), ('Fix the narrowest point.', 'Making a bottle fatter does not pour faster through the same neck.'), ('Excess per second × seconds.', 'One extra person every second for 900 seconds.'), ('Pressure concentrates where momentum and flows converge.', 'Water hammer where two pipes meet.')], '1.5': [('All arise from local rules without a leader.', 'Stripes, a swinging door, and a ripple.'), ('Local advantage, repeated by many, becomes a global pattern.', "Ants following each other's trails."), ('Instability means the system has no slack.', 'A slinky about to tangle.'), ('Separate the conflicting flows.', 'Two doors: one marked IN, one marked OUT.'), ('Each person reacts to the one in front after a short delay.', 'Dominoes falling towards the back of the line.'), ('Act on the pattern before the count.', 'A kettle starting to whistle: turn down the heat.')], '1.6': [('Known routes feel safe.', 'Homing pigeons returning through the same window.'), ('Blaming behaviour hides fixable causes.', 'Blaming water for a flooded basement while the tap runs.'), ('The busy exit sets the total time.', '960 people through one door, three at a time.'), ('Social bonds are part of the physics.', 'A family as a slow, wide raft.'), ('Information must be understood to work.', 'A traffic light needs no translation.'), ('Information does not travel back through a dense crowd.', 'A long queue where only the front sees the closed door.')], '1.7': [('Below that, people can still choose small movements.', 'Six people on one bath mat.'), ('Dense and irregular means danger; dense and orderly is less dangerous.', 'A pressure cooker needs both heat (density) and boiling (irregular motion).'), ('Each link is a place to intervene.', 'A row of dominoes: remove an early one.'), ('One route for both directions.', 'A single door used by people going in and out at once.'), ('Patterns and behaviour show danger before counts.', 'Smoke before fire.'), ('Numbers travel badly between sites and methods.', 'A single thermometer reading in one room.')], '1.8': [('What you control, at each phase.', 'A dim ice cube with nine frozen squares.'), ('Where, how much space, when, and who.', 'A ramp with four steps: route, area, movement, profile.'), ('Width = people ÷ (rate × time).', '66 people per metre per minute on the stairs.'), ("RAMP's P matters as much as its A.", 'A school trip and a marathon finish in the same park.'), ('Plans need operations.', 'A traffic police officer with a stop sign.'), ('Arrivals spread out; departures do not.', 'A cinema emptying when the credits roll.')], '2.1': [("It is a person's path with timestamps.", "A snail's silver trail with a clock on each blob."), ('Shares change smoothly; counts change in jumps.', 'Sharing a pizza by slices instead of whole pizzas.'), ('Divide by time, then width.', 'Two people a second through four one-metre lanes.'), ('Three measurements, one law.', 'A recipe check: flour × batches should equal the loaves.'), ('Data plus a tool.', 'A library card and a calculator.'), ('Triangulate imperfect sources.', 'Three cheap watches agree better than one.')], '2.2': [('People do not appear or vanish.', "A bucket's level changes by water in minus water out."), ('Both sides must agree to a transfer.', 'A courier can only deliver what the sender has and the receiver can store.'), ('Supply scales with width.', 'Half a door, half the flow.'), ('Excess inflow piles up behind.', "A traffic jam's end creeps towards approaching cars."), ('Direction comes from the fastest route.', 'Water flowing downhill, where the hills are travel times.'), ('Pick the scale that answers the question.', 'A weather map, not a raindrop simulator.')], '2.3': [('One person per cell prevents overlaps.', 'A floor tile just big enough for two shoes.'), ('Knowing the way versus following others.', 'A downhill slope and footprints in snow.'), ('One cell per step at most.', 'One tile every third of a second.'), ('The rules allow perfect, conflict-free throughput.', 'A turnstile that never jams.'), ('Fit the model to data.', 'Tighten the turnstile until it matches the real one.'), ('Trails attract.', 'Ants on a pheromone trail.')], '2.4': [('Goal, others, environment.', 'A dog on a lead (goal), other dogs (people), and fences (walls).'), ('A spring with a time constant.', 'How fast a cyclist gets back to cruising speed.'), ('More push, more blocking.', 'Shaking a salt cellar too hard so the grains jam.'), ('Strength, range, reaction time.', '2,000 newtons within 8 centimetres, in half a second.'), ('Stiff springs need fine time slices.', 'Filming a bouncing ball needs a fast camera.'), ('Report choices and checks.', 'A powerful car that needs a careful driver.')], '2.5': [('From aggregate numbers to individual decisions.', 'A ladder from a slide rule to binoculars.'), ('Safe following distance, like cars.', 'Keep a one-second gap to the person ahead.'), ('Direction from vision, speed from a safety gap.', 'Look for the clearest path, then keep a gap.'), ('Scale first.', 'A city map, not a microscope.'), ('Model choice is an assumption.', 'Asking three doctors for a second opinion.'), ('Open tools let you compare.', 'Vadere takes steps; JuPedSim keeps its distance.')], '2.6': [('Time, not distance, is what people care about.', 'A satnav that knows about traffic.'), ('Queue time dominates.', '500 seconds of queuing, 25 of walking.'), ('Balance the last person at each exit.', 'Two checkout queues should empty together.'), ('Selfish versus collective best.', 'Every driver for themselves versus a traffic controller.'), ('Networks can surprise.', 'A shortcut that everyone jams.'), ('Change information, change choices.', 'A sign saying: shorter queue this way.')], '2.7': [('Something must be noticed, announced, acted on and walked.', 'A smoke alarm, a loudspeaker, a person putting on a coat, and a pair of running shoes.'), ('Simply add the parts.', 'Four coins in a jar.'), ('Humans, not physics, set it.', 'Waiting for everyone to find their shoes.'), ('The slower process limits.', 'A short walk to a long queue.'), ('Plan for the bad day, not the average day.', 'Weather forecasts give ranges, not one temperature.'), ('Attack the biggest part.', 'A clear voice saying: leave now by the left exit.')], '2.8': [('Right code, right parameters, right predictions.', 'Check the oven works, set the temperature, taste a new cake.'), ('One target leaves too much freedom.', 'A suit that fits the shoulders but not the sleeves.'), ('Square, average, root.', 'The typical size of a miss.'), ('Memorising is not understanding.', "A student who learned last year's exam answers."), ('Benchmarks every simulator should pass.', 'A driving test for simulators.'), ('Be honest about the error bars.', 'A forecast with a range, not one number.')], '3.1': [('Who, what changes, against what, measured how.', 'A PICnic Of four sandwiches.'), ('Duration and numbers both drive harm.', 'A short splash vs a long soak.'), ('Density × area × time.', '5,000 people standing for 12 minutes.'), ('Factors can combine in surprising ways.', 'Salt and sugar together taste different from each alone.'), ('Privacy by design.', 'A camera that counts heads but forgets faces.'), ('Scale and stakes limit methods.', 'You cannot rehearse the Hajj.')], '3.2': [('Relieving one crush created another.', 'Pouring into a full glass.'), ('Swiss-cheese holes lining up.', 'Several slices of cheese whose holes line up.'), ('One route for both directions.', 'One door for a crowded room.'), ('Even basic facts can be contested.', 'Two scorekeepers who never compared notes.'), ('No organiser means every cell is empty.', 'A party with no host.'), ('Ask what was known then.', 'Reading the last page of a mystery first.')], '3.3': [('Religion sets the timetable.', 'A whole city setting the same alarm clock.'), ('Spread vertically, separate directions.', 'A five-storey cake with one-way ramps.'), ('Per-slot demand must fit capacity.', 'Six buses for 450 passengers that seat 60 each.'), ('Deviations are correlated, not random.', 'Everyone deciding to beat the rush at the same time.'), ('Robustness, feedback, vulnerability, privacy.', 'A plan, a dashboard, a thermometer and a lock.'), ('Organisation enables management.', 'A tour guide with a timetable.')], '3.4': [('Area × density, summed.', 'Tiling the square and counting heads per tile.'), ('Multiply and add.', 'Two carpets with different crowds.'), ('Estimate, then integrate.', 'A heat map whose heat adds up to people.'), ('Honesty about uncertainty.', 'A fishing tale with honest arms.'), ('Phones are not people.', 'Counting umbrellas to count people.'), ('Privacy by design.', 'A camera that sees crowds, not faces.')], '3.5': [('Dense and irregular.', 'Pressure needs both packing and shaking.'), ('Decide in advance what you will do.', 'A fire alarm that also unlocks the doors.'), ('Late warnings cannot help.', 'A weather warning after the storm.'), ('Multiply density by variance.', 'Six people shaking a little each.'), ('Technology needs organisation.', 'A smoke detector nobody listens to.'), ('See around the corner.', 'A satnav warning of traffic ahead.')], '3.6': [('A chain where every link matters.', 'A recipe from ingredients to plating.'), ('The map is not the territory.', 'A floor plan without the furniture.'), ('A calibrated model should match data.', 'Just over one person per metre per second.'), ('Find what drives the answer.', 'Wiggling each knob to see which moves the needle.'), ('Scale and detail together.', 'A city map with zoomed-in inserts.'), ('Enough for someone else to rerun it.', 'A recipe with exact quantities and oven settings.')], '3.7': [('Rate, space, time and information.', 'A tap, a one-way sign, a pen and a clock.'), ('Conservation of people.', 'Squeezing a balloon: the air moves.'), ('Inflow minus metered rate.', 'A bath filling at 120 cups a minute.'), ('Like with like.', 'Two runners on the same track.'), ('People adapt.', 'Water finding a way around a dam.'), ('Move waiting to safer ground.', 'Queue in the park, not in the corridor.')], '3.8': [('Physics, people, technology, health.', 'Five signposts at a crossroads.'), ('Crowds are social systems.', 'A football crowd and a choir move differently in the same hall.'), ('Precision must match uncertainty.', 'Measuring a cloud with a micrometre.'), ('Honesty builds trust.', 'A map that marks the areas it has not surveyed.'), ('Models are conditional.', 'A weather model cannot promise sunshine.'), ('Clear, honest, actionable.', 'A one-page brief with a traffic-light summary.')]}
PALACE = {1: {'place': 'Your home', 'intro': "Walk through your own home, front door to garden gate. In each room, picture the strange scene and let it hand you the module's core idea.", 'stations': [('1.1', 'Front door', 'A giant bathtub blocks your front door. A tap labelled ARRIVALS gushes people; a tiny plughole labelled GATE lets them out one by one. The water keeps rising long after the tap starts to slow.'), ('1.2', 'Hallway', 'Your hallway floor is a giant report card with squares marked A to F. In square A one person dances alone; in square F six people are pressed like books on a shelf, unable to lift their arms.'), ('1.3', 'Kitchen', 'A conveyor belt runs across your kitchen counter carrying tiny walkers. As you pile more on, the belt slows; the number dropping off the end rises, hits a peak of 1.2 a second, then falls.'), ('1.4', 'Bathroom doorway', 'Your bathroom doorway has shrunk to the width of a zip. Tiny people line up and interleave like zip teeth as they pass; behind them the queue swells into the bath.'), ('1.5', 'Living room', 'Two armies of toy soldiers march across your living-room carpet in opposite directions. Without a word they fall into neat stripes, until the room fills and ripples of stopping roll backwards like a wave in a stadium.'), ('1.6', 'Study', 'In your study, a crowd of tiny people ignores a glowing open door and squeezes back through the mouse hole they came in by, holding hands in chains of three, while a helpful stranger points at the empty door.'), ('1.7', 'Stairwell', 'On your stairs, a thick crowd of people stands still, then sways like a field of wheat in a gale; a pressure gauge on the banister swings past the red line marked 0.02.'), ('1.8', 'Garden gate', 'At your garden gate a steward holds a board with nine squares (DIM × ICE) and a stopwatch reading 8:00; a tape measure unrolls 9.1 metres as 6,000 garden gnomes walk out in rows of 82.')]}, 2: {'place': 'A modelling workshop', 'intro': 'Walk through a busy workshop where crowd models are built, bench by bench. Each bench holds one model with its own odd scene.', 'stations': [('2.1', 'Camera bench', 'On the first workbench, a camera on a stalk looks down on wind-up walkers trailing glowing threads; a tiler lays a Voronoi mosaic under their feet, one tile each.'), ('2.2', 'Plumbing bench', 'On the second bench, a long glass pipe carries honey-coloured people; a pinch halfway along makes them pile up, and the edge of the pile creeps back towards you like a slow tide.'), ('2.3', 'Chessboard bench', 'On the third bench, a giant chessboard where every square holds one walker; the board slopes towards a door like a funnel, and behind each walker a trail of glowing breadcrumbs fades away.'), ('2.4', 'Spring bench', 'On the fourth bench, wooden figures are tied to a door by elastic bands and wear spiky balloons that push each other apart; when you pull the bands hard they jam in an arch and nobody gets through.'), ('2.5', 'Toolbox bench', 'On the fifth bench sits a toolbox with seven drawers: a slide rule, a jug of honey, a chessboard, springs, a speedometer, a pair of hopping boots, and a pair of binoculars. A label says: pick the drawer for the job.'), ('2.6', 'Signpost bench', 'On the sixth bench, a signpost with two arms, NEAR and FAR. A crowd of marbles rolls towards NEAR and jams; a tiny steward flips half of them towards FAR, and both piles empty at the same moment.'), ('2.7', 'Clock bench', "On the seventh bench, two big clocks race. ASET's clock is wrapped in smoke; RSET's clock has four hands, and one fat hand labelled PRE-MOVEMENT sometimes stops to look for its friends."), ('2.8', 'Test bench', 'On the last bench, a tailor fits a suit on one mannequin (calibration), then tries it on its twin hidden behind a curtain (validation), while a referee holds up a RiMEA scorecard.')]}, 3: {'place': 'A pilgrimage route', 'intro': 'Walk the route of a great pilgrimage, from the arrival camp to the final rite. Each stop is one research module.', 'stations': [('3.1', 'Arrival camp', 'At the arrival camp, a scholar at a folding table writes one sharp question on a lantern; around it, tents are labelled EXPOSURE, SCENARIOS, DATA and ETHICS, each with a padlock that only opens with permission.'), ('3.2', 'Memorial gate', 'At the memorial gate on the route, four stones stand in a row, each carved with a date and a shape: a full glass, a single ramp, two rivers meeting, and a funnel fed from both ends. A DIM-ICE grid is chiselled into the arch above.'), ('3.3', 'Jamarat bridge', 'At the bridge, a five-storey cake stands with ramps spiralling up its sides like a helter-skelter; every slice has an arrow pointing one way only, and a timekeeper at the bottom hands each group a coloured hourglass.'), ('3.4', 'Watchtower', 'At the watchtower, a lighthouse sweeps a beam that paints a glowing density map on the crowd below; a man with a chalk grid multiplies zones, while a giant phone on the roof counts pings with its screen blacked out for privacy.'), ('3.5', 'Control tent', 'Inside the control tent, a wall of screens glows green except one cell turning red; a big lever marked ACT is within reach of a steward wearing a sash that says AUTHORISED, and a clock on the wall shows 30 minutes to spare.'), ('3.6', 'Model tent', 'In the model tent, a sand table holds a tiny copy of the route; dice roll on it again and again, each throw a seed, while an assistant chalks the 95th percentile on a blackboard and files the code in a labelled box.'), ('3.7', 'Waiting square', 'At the waiting square, a gatekeeper turns a tap that drips people into a fenced plaza; outside, the queue coils like a garden hose on an open field, and a referee compares two scoreboards labelled BEFORE and AFTER.'), ('3.8', 'Farewell gate', 'At the farewell gate, five signposts point to unexplored valleys labelled PUSHING, PSYCHOLOGY, AI, TWINS and HEAT; a scribe at a lectern writes a report in which every number carries a little pair of brackets for its range.')]}}
